/* --- 微凉夜 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. --- */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=DotGothic16&display=swap');
@import url("https://fontsapi.zeoseven.com/292/main/result.css");
@import url("https://fontsapi.zeoseven.com/45/main/result.css");
@import url("https://fontsapi.zeoseven.com/521/main/result.css");
@import url("https://fontsapi.zeoseven.com/811/main/result.css");

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #090d1a;
    --panel-bg-color: rgba(15, 23, 42, 0.85);
    --panel-bg-hover: rgba(30, 58, 138, 0.95);
    --card-bg: rgba(11, 17, 32, 0.85);
    --input-bg: rgba(15, 23, 42, 0.9);
    --text-main: #e2e8f0;
    --text-subtle: #93c5fd;
    --accent-blue: #3b82f6;
    --accent-lightblue: #60a5fa;
    --accent-white: #ffffff;
    --font-pixel: 'DotGothic16', monospace;
    --font-main: "LXGW WenKai", var(--font-pixel);
    --font-quote: "JetBrains Maple Mono", var(--font-pixel);
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "ChangBanDianSong 16 SC", var(--font-pixel);
}

/* --- 3. 全局样式与像素化设定 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg) !important; 
    background-image: linear-gradient(rgba(9, 13, 26, 0.7), rgba(15, 23, 42, 0.8));
    background-size: cover; background-position: center; background-attachment: fixed;
    color: var(--text-main); font-family: var(--font-main); font-weight: normal; 
}
/* 全局悬浮小物粒子 */
body::after {
    content: ''; position: fixed; top: 10%; left: 5%; width: 200px; height: 200px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/HfWJ/2252X2252/2026-04-27_113718.png/webp');
    background-size: contain; background-repeat: no-repeat; opacity: 0.8;
    pointer-events: none; z-index: 9999;
    animation: pixel-float 6s infinite alternate steps(10);
}
@keyframes pixel-float { 0% { transform: translateY(0) scale(1); } 100% { transform: translateY(-20px) scale(1.05); } }

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 180px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-white); font-weight: normal; text-shadow: 2px 2px 0px var(--accent-blue); }

/* --- 4. 顶部导航栏 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); border: none; border-bottom: 3px solid var(--accent-white) !important; outline: 2px solid var(--accent-blue) !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(3); image-rendering: pixelated; }
.drawer-icon.fa-fw:hover { transform: translateY(-4px); filter: drop-shadow(0 4px 0px var(--accent-blue)); }
/* 图标 URL ... */
.drawer-icon.fa-sliders, #ai-config-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/E51m/2252X2252/2026-04-27_103858.png/webp'); }
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/52wG/2252X2252/2026-04-27_103841.png/webp'); }
.drawer-icon.fa-font, #advanced-formatting-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/E51m/2252X2252/2026-04-27_103858.png/webp'); }
.drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/52wG/2252X2252/2026-04-27_103841.png/webp'); }
.drawer-icon.fa-user, #user-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/E51m/2252X2252/2026-04-27_103858.png/webp'); }
.drawer-icon.fa-image, .drawer-icon.fa-panorama { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/52wG/2252X2252/2026-04-27_103841.png/webp'); }
.drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/E51m/2252X2252/2026-04-27_103858.png/webp'); }
.drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/52wG/2252X2252/2026-04-27_103841.png/webp'); }
.drawer-icon.fa-face-smile, #persona-management-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/E51m/2252X2252/2026-04-27_103858.png/webp'); }
.drawer-icon.fa-address-card, #character_popup_button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/52wG/2252X2252/2026-04-27_103841.png/webp'); }

/* 抽屉与弹窗背景图 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(9, 13, 26, 0.8), rgba(15, 23, 42, 0.9)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/fx9N/1200X800/e6f68bf545dde44866b538afff731c6b.jpg/webp') !important;
    background-size: cover; background-position: center;
    border: 2px solid var(--accent-white) !important; outline: 2px solid var(--accent-blue) !important; border-radius: 0;
}

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 25px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; overflow: visible !important; }
#send_form { 
    pointer-events: auto; width: 80% !important; max-width: 800px !important; margin: 0 auto !important; 
    background-color: var(--input-bg) !important; padding: 10px 15px !important; 
    backdrop-filter: blur(10px) !important; position: relative; 
    border: 2px solid var(--accent-white) !important;
    outline: 3px solid var(--accent-blue) !important;
    border-radius: 0 !important;
    animation: form-float-anim 3s infinite alternate steps(4);
}
@keyframes form-float-anim { 0% { transform: translateY(0); } 100% { transform: translateY(-6px); } }
#send_form:hover { background-color: var(--panel-bg-hover) !important; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }
#send_form::before {
    content: ''; position: absolute; left: -65px; top: -15px; width: 100px; height: 100px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/TegM/2252X2252/2026-04-27_093652.png/webp');
    background-size: contain; background-repeat: no-repeat; z-index: 50; pointer-events: none;
    animation: wing-flap-left 2s infinite alternate steps(3);
}
#send_form::after {
    content: ''; position: absolute; right: -65px; top: -15px; width: 100px; height: 100px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/Q6J9/2252X2252/2026-04-27_093712.png/webp');
    background-size: contain; background-repeat: no-repeat; z-index: 50; pointer-events: none;
    animation: wing-flap-right 2s infinite alternate steps(3);
}
@keyframes wing-flap-left { 0% { transform: translateY(0) rotate(-5deg); } 100% { transform: translateY(-8px) rotate(5deg); } }
@keyframes wing-flap-right { 0% { transform: translateY(0) rotate(5deg); } 100% { transform: translateY(-8px) rotate(-5deg); } }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '夜の風が吹いている...'; 
    color: var(--accent-lightblue); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); 
    font-family: var(--font-pixel); font-size: clamp(11px, 2vw, 16px); pointer-events: none; z-index: 10; 
    white-space: nowrap; letter-spacing: 1px; 
    opacity: 0.7; animation: pixel-blink 1.5s infinite steps(2);
}
@keyframes pixel-blink { 0% { opacity: 0.2; } 100% { opacity: 1; } }
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 34px; height: 34px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.2s steps(2); font-size: 0; border: none; background-color: transparent; image-rendering: pixelated; margin: 0 2px; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: translateY(-3px) scale(1.1); }
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/aQ88/2252X2252/2026-04-27_103910.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/1HEO/2252X2252/2026-04-27_103744.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/DuVB/2252X2252/2026-04-27_085918.png/webp'); }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/aQ88/2252X2252/2026-04-27_103910.png/webp'); filter: hue-rotate(180deg); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/1HEO/2252X2252/2026-04-27_103744.png/webp'); filter: hue-rotate(90deg); }

/* --- 6. 核心：消息卡片 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; margin: 55px auto 110px !important; 
    width: 85%; max-width: 800px; 
    border: 2px solid var(--accent-white) !important; outline: 2px solid var(--accent-blue) !important; border-radius: 0 !important;
    backdrop-filter: blur(5px) !important; overflow: visible !important; position: relative; 
}
.mes[is_user="false"] { background: var(--card-bg) !important; }
.mes[is_user="true"] { background: rgba(15, 30, 55, 0.85) !important; border-color: var(--accent-lightblue) !important; outline-color: var(--accent-white) !important; }
.mes .mesAvatarWrapper::before {
    content: ''; position: absolute; top: -45px; right: -40px; width: 120px; height: 120px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/v4H6/2252X2252/2026-04-27_103928.png/webp');
    background-size: contain; background-repeat: no-repeat; z-index: 100; pointer-events: none;
    animation: float-cloud 4s infinite alternate steps(4);
}
@keyframes float-cloud { 0% { transform: translateY(0); } 100% { transform: translateY(-10px); } }
.mes::before {
    content: ''; position: absolute; bottom: -30px; left: 50%; transform: translateX(-50%);
    width: 90%; height: 26px; 
    background-color: var(--panel-bg-color);
    border: 2px solid var(--accent-white); outline: 2px solid var(--accent-blue);
    z-index: 5; pointer-events: none; 
}
.mes::after {
    content: ''; position: absolute; bottom: -100px; left: 50%; transform: translateX(-50%);
    width: 180%; height: 180px; 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/DprI/2252X2252/2026-04-27_094342.png/webp');
    background-size: contain; background-position: center bottom; background-repeat: no-repeat;
    z-index: 20; pointer-events: none; image-rendering: pixelated;
}
.mes .mesAvatarWrapper {
    display: flex; justify-content: center; align-items: center; padding: 0;
    width: 100%; height: 160px !important; min-height: 160px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-bottom: 2px solid var(--accent-white);
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/Cuis/500X288/qxDeG_gif_%28500%C3%97288%29.gif/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260427/dITW/639X361/%E4%B8%8B%E8%BD%BD.gif'); }
.mes .avatar {
    position: absolute; top: 20px; width: 100px; height: 100px; 
    background: #090d1a !important; 
    padding: 4px !important; 
    border: 2px solid var(--accent-white) !important; outline: 2px solid var(--accent-blue) !important;
    z-index: 30; display: flex !important; align-items: center; justify-content: center;
    border-radius: 0 !important; box-shadow: 6px 6px 0px rgba(59, 130, 246, 0.4) !important;
}
.mes[is_user="false"] .avatar { left: -30px; }
.mes[is_user="true"] .avatar { right: -30px; left: auto; }
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 0 !important; border: none !important; image-rendering: pixelated; }
.mes .avatar::after {
    position: absolute; bottom: -20px; right: -40px; padding: 2px 6px;
    background: var(--accent-blue); border: 2px solid var(--accent-white);
    color: #fff; font-family: var(--font-pixel); font-size: 12px; font-weight: bold;
    white-space: nowrap; z-index: 40; box-shadow: 2px 2px 0px rgba(0,0,0,0.5);
}
.mes[is_user="false"] .avatar::after { content: '💬 会話中...'; }
.mes[is_user="true"] .avatar::after { content: '▶ コマンド'; right: auto; left: -40px; background: var(--accent-lightblue); }
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 25px 25px 35px 25px !important; position: relative; border: none !important; overflow: visible !important; min-height: 80px !important; z-index: 10; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }

/* --- 思维链日系自定义 --- */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "⚙️ システム処理中 [思考ロード]..."; 
    font-family: var(--font-pixel); font-size: 14px !important; 
    color: var(--accent-lightblue); visibility: visible; letter-spacing: 1px; 
    text-shadow: 1px 1px 0px #000;
}
.mes_reasoning { border-left: 4px solid var(--accent-blue) !important; padding-left: 15px !important; margin-bottom: 20px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 0.95em; }
.mes .mes_text { line-height: 1.8; color: var(--text-main); font-size: 16px; text-align: justify; }

/* --- 排版与文字特效 --- */
.mes_text h1 { font-family: var(--font-title); color: var(--accent-white); font-size: 1.8em; text-align: center; position: relative; padding-bottom: 10px; margin: 25px 0 15px 0; border-bottom: 2px dashed var(--accent-blue) !important; font-weight: normal; }
.mes_text h1::before { content: '【 '; color: var(--accent-lightblue); } .mes_text h1::after { content: ' 】'; color: var(--accent-lightblue); }
.mes_text h2 { font-family: var(--font-title); color: var(--accent-lightblue); font-size: 1.5em; padding: 4px 0 4px 15px; border-left: 6px solid var(--accent-blue) !important; margin: 20px 0 10px 0; background: linear-gradient(to right, rgba(59, 130, 246, 0.2) 0%, transparent 100%); font-weight: normal; }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: normal !important; color: var(--text-subtle); background: rgba(59, 130, 246, 0.15); padding: 2px 4px; outline: 1px dashed var(--accent-blue); }
.mes_text strong, .mes_text b { font-family: var(--font-main); color: var(--accent-white); font-weight: bold; text-shadow: 1px 1px 2px var(--accent-blue); }
.mes_text blockquote { background-color: rgba(9, 13, 26, 0.6); border: 2px solid var(--accent-blue) !important; border-left: 6px solid var(--accent-lightblue) !important; padding: 12px 18px; margin: 15px 0; font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text span.quote, .mes_text q, .mes_text .dialogue { font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text code { font-family: var(--font-code) !important; background-color: rgba(0, 0, 0, 0.7) !important; color: var(--accent-lightblue) !important; padding: 4px 8px; border: 1px solid var(--accent-blue) !important; }

/* --- 角色名单独外提：RPG 小名片 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }
.mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    top: -180px !important; 
    width: auto !important; height: auto !important;
    background: var(--card-bg) !important; 
    border: 2px solid var(--accent-white) !important; 
    outline: 2px solid var(--accent-blue) !important; 
    padding: 6px 16px !important; 
    z-index: 120; 
    box-shadow: 4px 4px 0px rgba(59, 130, 246, 0.5) !important; 
}
.mes[is_user="false"] .mes_block > .ch_name { left: 15px !important; right: auto !important; justify-content: flex-start !important; }
.mes[is_user="true"] .mes_block > .ch_name { right: 15px !important; left: auto !important; justify-content: flex-end !important; }
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; flex-wrap: nowrap !important; }
.mes .ch_name .name_text { 
    font-family: var(--font-pixel) !important; font-size: 20px !important; 
    color: var(--accent-white) !important; text-shadow: 2px 2px 0px var(--accent-blue); 
    background: transparent !important; padding: 0 !important; border: none !important; line-height: 1;
}

/* 日系楼层 ID */
.mes .mesIDDisplay {
    position: absolute; top: 165px !important; 
    background: #090d1a !important; border: 2px solid var(--accent-white) !important; outline: 2px solid var(--accent-blue) !important;
    color: var(--accent-white) !important; font-size: 14px !important; z-index: 100; 
    padding: 4px 12px !important; white-space: nowrap; line-height: 1 !important; border-radius: 0 !important;
    left: 50% !important; transform: translateX(-50%) !important; right: auto !important; 
    font-family: var(--font-pixel);
}
.mesIDDisplay::before { content: 'セーブデータ ['; color: var(--accent-lightblue); }
.mesIDDisplay::after { content: ']'; color: var(--accent-lightblue); }
.mes .mes_timer { position: static !important; color: #64748b !important; font-size: 12px !important; font-family: var(--font-pixel); background: #000; padding: 2px 6px; border: 1px solid #333; }

/* --- 编辑与互动按钮 (图标修复版) --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 6px; position: static !important; opacity: 0.3; transition: opacity 0.2s steps(2); pointer-events: auto !important; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
/* 所有消息按钮基础样式 */
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button {
    background-color: var(--card-bg) !important; padding: 0 !important;
    cursor: pointer;
    height: 28px !important; width: 28px !important;
    border: 2px solid var(--accent-blue) !important; border-radius: 0 !important;
