/* --- 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, div[name*='Toggles'] h4 { background: var(--card-bg) !important; border: 2px solid var(--accent-blue) !important; border-radius: 0 !important; padding: 10px 15px !important; margin-bottom: 8px !important; color: var(--accent-white) !important; font-family: var(--font-pixel); }
